const STORE_KEY='nexora-three-files-v1';
let currentRoute='/';
function state(){const stored=localStorage.getItem(STORE_KEY);return stored?JSON.parse(stored):{projects:SEEDS.map(p=>({...p})),inquiries:[],fanpageUrl:''};}
function save(s){localStorage.setItem(STORE_KEY,JSON.stringify(s));}
const response=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json'}});
async function localFetch(path,options={}){try{const url=new URL(path,'https://local.test');const s=state(),method=options.method||'GET',body=typeof options.body==='string'?JSON.parse(options.body):{};
if(url.pathname==='/api/admin/me')return response({email:'Bản cục bộ · thiết bị này'});
if(url.pathname==='/api/admin/projects'&&method==='GET')return response(s.projects.filter(p=>p.status!=='deleted'));
if(url.pathname==='/api/projects'){let list=s.projects.filter(p=>p.status==='published');const category=url.searchParams.get('category');if(category)list=list.filter(p=>p.category===category);return response(list);}
if(url.pathname.startsWith('/api/projects/')){const p=s.projects.find(p=>p.slug===decodeURIComponent(url.pathname.split('/')[3])&&p.status==='published');return p?response(p):response({error:'Dự án không tồn tại hoặc chưa công bố.'},404);}
if(url.pathname==='/api/admin/projects'&&method==='POST'){const id=crypto.randomUUID?crypto.randomUUID():String(Date.now());const p={...body,id,slug:'du-an-'+id,theme:'custom',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};s.projects.unshift(p);save(s);return response(p,201);}
if(url.pathname.startsWith('/api/admin/projects/')){const id=decodeURIComponent(url.pathname.split('/')[4]);const i=s.projects.findIndex(p=>p.id===id);if(i<0)return response({error:'Không tìm thấy dự án.'},404);if(method==='DELETE'){s.projects[i].status='deleted';save(s);return response({ok:true});}if(method==='PUT'){s.projects[i]={...s.projects[i],...body,id,updatedAt:new Date().toISOString()};save(s);return response(s.projects[i]);}}
if(url.pathname==='/api/admin/uploads'){const file=options.body.get('file');if(!file||file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))return response({error:'Chọn ảnh JPG/PNG/WEBP tối đa 5 MB.'},400);const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});return response({url:data},201);}
if(url.pathname==='/api/admin/inquiries')return response(s.inquiries);
if(url.pathname==='/api/contact'){if(!body.name||!body.message||!/^\S+@\S+\.\S+$/.test(body.email||''))return response({error:'Điền tên, email hợp lệ và lời nhắn.'},400);s.inquiries.unshift({...body,id:String(Date.now()),created_at:new Date().toISOString()});save(s);return response({ok:true},201);}
if(url.pathname==='/api/settings'||url.pathname==='/api/admin/settings'){if(method==='PUT'){if(body.fanpageUrl&&!/^https:\/\//.test(body.fanpageUrl))return response({error:'Link fanpage phải bắt đầu bằng https://'},400);s.fanpageUrl=body.fanpageUrl;save(s);}return response({fanpageUrl:s.fanpageUrl});}
return response({error:'Không có chức năng này.'},404);
}catch{return response({error:'Không lưu được dữ liệu. Bộ nhớ trình duyệt có thể đã đầy hoặc bị chặn. Hãy giảm kích thước ảnh.'},500);}}
function go(path){location.hash='#'+(path==='/'?'/':path);}
function route(){if(location.hash&&!location.hash.startsWith('#/')&&document.getElementById('app').innerHTML)return;currentRoute=decodeURIComponent(location.hash.slice(1)||'/');const name=currentRoute.startsWith('/projects/')?'project':currentRoute==='/'?'index':currentRoute==='/admin'?'admin':currentRoute.replace(/^\//,'').replace(/\.html$/,'');const page=PAGES[name]?name:'404';document.getElementById('app').innerHTML=PAGES[page];document.title=(page==='index'?'NEXORA Creative Agency':page.toUpperCase()+' — NEXORA');document.querySelectorAll('a[href]').forEach(a=>{const href=a.getAttribute('href');if(href.startsWith('/')&&!href.startsWith('//'))a.setAttribute('href','#'+href);if(a.target==='_blank'&&a.href.includes('#/projects/'))a.removeAttribute('target');});mount(page);scrollTo(0,0);}
function mount(page){const fetch=localFetch;
const $=(s)=>document.querySelector(s);
const menuButton=$('.menu-toggle'),menu=$('.main-nav');
menuButton?.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'Đóng menu':'Mở menu');menu.classList.toggle('open',open);});
menu?.querySelectorAll('a').forEach(a=>{if(a.getAttribute('href')===location.hash)a.setAttribute('aria-current','page');a.addEventListener('click',()=>{menu.classList.remove('open');menuButton.setAttribute('aria-expanded','false');});});
if($('#year'))$('#year').textContent=new Date().getFullYear();
const labels={branding:'Branding',social:'Social',website:'Website'};
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function visual(p){const v=el('div','project-visual theme-'+p.theme);if(p.images?.length){const img=el('img','project-cover');img.src=p.images[0];img.alt=p.title;img.loading='lazy';v.append(img);}else if(p.theme==='luma'){v.append(el('div','luma-sun'),el('div','luma-title','luma®'),el('div','luma-caption','COFFEE FOR BRIGHTER DAYS.'));}else if(p.theme==='moc'){const frame=el('div','moc-frame');frame.append(el('span','','MỘC'),el('small','','STUDIO'),el('i','','Không gian cho những điều nguyên bản.'));v.append(frame);}else if(p.theme==='solace'){v.append(el('div','concept-word','solace'),el('div','concept-tagline','Feel good from within.'));}else{v.append(el('div','concept-word',p.title),el('div','concept-tagline',labels[p.category]));}if(p.concept)v.append(el('span','concept-badge','CONCEPT MINH HỌA'));return v;}
function card(p){const a=el('a','portfolio-card');a.href='#/projects/'+p.slug;a.append(visual(p));const info=el('div','project-meta'),main=el('div');main.append(el('span','',labels[p.category].toUpperCase()),el('h3','',p.title),el('p','',p.summary));info.append(main,el('span','project-index','Xem dự án ↗'));a.append(info);return a;}
let allProjects=[];
async function loadProjects(){const grids=document.querySelectorAll('[data-projects]');if(!grids.length)return;try{const r=await fetch('/api/projects');if(!r.ok)throw Error();allProjects=await r.json();grids.forEach(g=>renderProjects(g,g.dataset.projects));}catch{grids.forEach(g=>{g.replaceChildren(el('p','empty-state','Chưa tải được dự án. Vui lòng tải lại trang.'));});}}
function renderProjects(g,category){let list=allProjects.filter(p=>category==='all'||p.category===category);if(g.dataset.limit)list=list.slice(0,Number(g.dataset.limit));g.replaceChildren(...(list.length?list.map(card):[el('p','empty-state','Chưa có dự án được công bố trong dịch vụ này.')]));}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderProjects($('[data-projects]'),b.dataset.filter);}));
async function loadProject(){const target=$('#project-detail');if(!target)return;try{const slug=currentRoute.split('/')[2];const r=await fetch('/api/projects/'+encodeURIComponent(slug||''));const p=await r.json();if(!r.ok)throw Error(p.error);document.title=p.title+' — NEXORA';const back=el('a','text-link light','← Tất cả dự án');back.href='#/projects.html';const title=el('h1','project-title',p.title);const meta=el('p','section-kicker',labels[p.category].toUpperCase()+' / '+(p.concept?'CONCEPT MINH HỌA':'DỰ ÁN'));const intro=el('p','lead',p.summary);target.replaceChildren(back,meta,title,intro,visual(p));if(p.concept)target.append(el('p','concept-note','Đây là concept minh họa năng lực sáng tạo, không phải dự án khách hàng hoặc kết quả kinh doanh thực tế.'));const content=el('div','project-story');[['Khách hàng / thương hiệu',p.client],['Bài toán',p.challenge],['Giải pháp',p.solution],['Sản phẩm bàn giao',p.deliverables]].forEach(([h,t])=>{if(t){const row=el('article');row.append(el('h2','',h),el('p','',t));content.append(row);}});target.append(content);if(p.images?.length>1){const gallery=el('div','project-gallery');p.images.slice(1).forEach(src=>{const img=el('img');img.src=src;img.alt=p.title+' — hình ảnh dự án';img.loading='lazy';gallery.append(img);});target.append(gallery);}const link=el('a','button button-lime','Trao đổi dự án '+labels[p.category]+' ↗');link.href='#/contact.html';target.append(link);}catch(e){target.replaceChildren(el('h1','display-title','Chưa tìm thấy dự án.'),el('p','',e.message||'Vui lòng thử lại.'));}}
const contact=$('#contact-form');contact?.addEventListener('submit',async e=>{e.preventDefault();const button=contact.querySelector('button[type=submit]'),note=$('#form-note');button.disabled=true;note.textContent='Đang gửi lời nhắn…';try{const body=Object.fromEntries(new FormData(contact));const r=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw Error(result.error);go('/success.html');}catch(err){note.textContent=err.message||'Không gửi được lời nhắn. Vui lòng thử lại.';button.disabled=false;}});
async function loadContactSettings(){const link=$('#page-link');if(!link)return;try{const r=await fetch('/api/settings');const data=await r.json();if(data.fanpageUrl){link.href=data.fanpageUrl;link.hidden=false;}}catch{}}
loadProjects();loadProject();loadContactSettings();

if(page==='admin'){
let projects=[],editing=null,images=[];
const api=async(path,options={})=>{const r=await fetch('/api/admin/'+path,options);const data=await r.json();if(!r.ok)throw Error(data.error||'Không thể hoàn tất yêu cầu.');return data;};
const status=(text,error=false)=>{const n=document.getElementById('admin-status');n.textContent=text;n.classList.toggle('error',error);};
const editor=document.getElementById('project-editor');
function imageList(){const list=document.getElementById('image-list');list.replaceChildren();images.forEach((src,i)=>{const box=el('div','image-item'),img=el('img');img.src=src;img.alt='Ảnh dự án '+(i+1);const remove=el('button','secondary-button','Bỏ ảnh');remove.type='button';remove.addEventListener('click',()=>{images.splice(i,1);imageList();});box.append(img,remove);list.append(box);});}
function edit(p=null){editing=p;editor.reset();editor.hidden=false;document.getElementById('editor-title').textContent=p?'Sửa dự án':'Thêm dự án';for(const key of ['id','title','client','category','status','summary','challenge','solution','deliverables'])if(p)editor.elements.namedItem(key).value=p[key]||'';editor.elements.namedItem('concept').checked=p?p.concept:true;images=[...(p?.images||[])];imageList();editor.scrollIntoView({behavior:'smooth',block:'start'});}
async function load(){projects=await api('projects');const list=document.getElementById('admin-projects');list.replaceChildren();if(!projects.length)list.append(el('p','empty-state','Chưa có dự án. Thêm dự án đầu tiên để bắt đầu.'));projects.forEach(p=>{const row=el('article','admin-project-row'),copy=el('div');copy.append(el('h3','',p.title),el('p','small-note',labels[p.category]+' · '+(p.status==='published'?'Đã công bố':'Bản nháp')+(p.concept?' · Concept':'')));const actions=el('div','row-actions'),editButton=el('button','secondary-button','Sửa');editButton.addEventListener('click',()=>edit(p));actions.append(editButton);if(p.status==='published'){const preview=el('a','secondary-button','Xem ↗');preview.href='#/projects/'+p.slug;preview.target='_blank';preview.rel='noopener';actions.append(preview);}const remove=el('button','secondary-button danger','Xóa');remove.addEventListener('click',async()=>{if(!confirm('Xóa dự án “'+p.title+'” khỏi website?'))return;try{await api('projects/'+encodeURIComponent(p.id),{method:'DELETE'});if(editing?.id===p.id)editor.hidden=true;await load();status('Đã xóa dự án.');}catch(e){status(e.message,true);}});actions.append(remove);row.append(copy,actions);list.append(row);});}
document.getElementById('new-project').addEventListener('click',()=>edit());document.getElementById('cancel-editor').addEventListener('click',()=>{editor.hidden=true;});
document.getElementById('project-images').addEventListener('change',async e=>{const files=[...e.target.files];if(images.length+files.length>12){status('Mỗi dự án tối đa 12 ảnh.',true);e.target.value='';return;}const save=document.getElementById('save-project');save.disabled=true;try{for(const file of files){if(file.size>5*1024*1024)throw Error('Ảnh “'+file.name+'” vượt 5 MB.');status('Đang tải ảnh '+file.name+'…');const form=new FormData();form.append('file',file);const result=await api('uploads',{method:'POST',body:form});images.push(result.url);imageList();}status('Ảnh đã tải lên. Bấm Lưu dự án để hoàn tất.');}catch(err){status(err.message,true);}finally{save.disabled=false;e.target.value='';}});
editor.addEventListener('submit',async e=>{e.preventDefault();const button=document.getElementById('save-project');button.disabled=true;const data=Object.fromEntries(new FormData(editor));data.concept=editor.elements.namedItem('concept').checked;data.images=images;try{const p=await api(editing?'projects/'+encodeURIComponent(editing.id):'projects',{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});await load();editor.hidden=true;status(p.status==='published'?'Đã công bố dự án. Khách có thể xem ở portfolio và trang dịch vụ.':'Đã lưu bản nháp.');}catch(err){status(err.message,true);}finally{button.disabled=false;}});
async function inquiries(){const data=await api('inquiries'),list=document.getElementById('admin-inquiries');list.replaceChildren();if(!data.length)list.append(el('p','empty-state','Chưa có lời nhắn.'));data.forEach(p=>{const row=el('article','inquiry');row.append(el('h3','',p.name),el('p','small-note',p.email+' · '+p.service+' · '+new Date(p.created_at).toLocaleString('vi-VN')),el('p','inquiry-message',p.message));list.append(row);});}
document.querySelectorAll('[data-panel]').forEach(button=>button.addEventListener('click',async()=>{document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('active',b===button));for(const name of ['projects','inquiries','settings'])document.getElementById('panel-'+name).hidden=name!==button.dataset.panel;try{if(button.dataset.panel==='inquiries')await inquiries();if(button.dataset.panel==='settings'){const data=await api('settings');document.getElementById('settings-form').elements.namedItem('fanpageUrl').value=data.fanpageUrl||'';}}catch(e){status(e.message,true);}}));
document.getElementById('refresh-inquiries').addEventListener('click',()=>inquiries().catch(e=>status(e.message,true)));
document.getElementById('settings-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});status('Đã lưu cài đặt liên hệ.');}catch(err){status(err.message,true);}});
(async()=>{try{const user=await api('me');document.getElementById('admin-user').textContent=user.email;await load();}catch(e){status(e.message,true);}})();

}
}
window.addEventListener('hashchange',route);route();
